const upsertOAuthLink = `-- name: UpsertOAuthLink :one

INSERT INTO oauth_links (user_id, provider, external_id, email)
VALUES ($1, $2, $3, $4)
ON CONFLICT (provider, external_id) DO UPDATE SET email = EXCLUDED.email
RETURNING user_id, provider, external_id, email, created_at
`

type UpsertOAuthLinkParams struct {
	UserID     uuid.UUID
	Provider   string
	ExternalID string
	Email      string
}

// ─── oauth_links ────────────────────────────────────────────────────────────
func (q *Queries) UpsertOAuthLink(ctx context.Context, arg UpsertOAuthLinkParams) (OauthLink, error) {
	row := q.db.QueryRow(ctx, upsertOAuthLink,
		arg.UserID,
		arg.Provider,
		arg.ExternalID,
		arg.Email,
	)
	var i OauthLink
	err := row.Scan(
		&i.UserID,
		&i.Provider,
		&i.ExternalID,
		&i.Email,
		&i.CreatedAt,
	)
	return i, err
}

